INSERT INTO categorias (nombre, descripcion) VALUES
  ('Seguridad eléctrica', 'Conceptos generales para reconocer riesgos eléctricos y medidas de protección.'),
  ('Cables eléctricos', 'Conceptos sobre conductores, cables y canalizaciones, sin especificar dimensionamientos.'),
  ('Herramientas eléctricas', 'Instrumentos y herramientas utilizados por personal competente.'),
  ('Materiales eléctricos', 'Elementos habituales de una instalación eléctrica.'),
  ('Protecciones eléctricas', 'Dispositivos y sistemas destinados a reducir riesgos eléctricos.'),
  ('Fallas eléctricas', 'Fenómenos que pueden afectar el funcionamiento y la seguridad de una instalación.')
INSERT INTO terminos (categoria_id, nombre, descripcion, importancia) VALUES
  ((SELECT id FROM categorias WHERE nombre = 'Seguridad eléctrica'), 'Riesgo eléctrico', 'Posibilidad de daño por exposición a la energía eléctrica. La evaluación y prevención dependen de la instalación, las condiciones de uso y la reglamentación aplicable.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Seguridad eléctrica'), 'Contacto directo', 'Contacto de una persona con una parte activa normalmente energizada. La protección debe ser definida y verificada por personal competente.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Seguridad eléctrica'), 'Contacto indirecto', 'Contacto con una parte conductora accesible que puede quedar energizada debido a una falla de aislación.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Seguridad eléctrica'), 'Puesta a tierra', 'Conexión de partes de una instalación a un sistema de puesta a tierra como parte de las medidas de protección. Su diseño y verificación dependen de la reglamentación aplicable.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Seguridad eléctrica'), 'Elementos de protección personal', 'Equipos seleccionados para reducir la exposición a riesgos durante tareas determinadas. No reemplazan las medidas de protección de la instalación ni la capacitación.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Seguridad eléctrica'), 'Desenergización', 'Estado de una instalación o parte de ella sin alimentación eléctrica. Debe ser establecido y controlado por personal competente; no se debe asumir por la posición de un interruptor.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Seguridad eléctrica'), 'Verificación de ausencia de tensión', 'Comprobación realizada con instrumentos y procedimientos adecuados por personal competente. La apariencia o el estado de un mando no confirma por sí solo que no haya tensión.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Cables eléctricos'), 'Cable unipolar', 'Cable que contiene un solo conductor aislado. Su selección depende del tipo de instalación y de las condiciones de uso.', 'informativa'),
  ((SELECT id FROM categorias WHERE nombre = 'Cables eléctricos'), 'Cable bipolar', 'Cable que contiene dos conductores aislados reunidos bajo una cubierta común, cuando el diseño del cable así lo establece.', 'informativa'),
  ((SELECT id FROM categorias WHERE nombre = 'Cables eléctricos'), 'Cable multipolar', 'Cable que contiene varios conductores aislados reunidos bajo una cubierta común. La cantidad y construcción dependen del producto.', 'informativa'),
  ((SELECT id FROM categorias WHERE nombre = 'Cables eléctricos'), 'Conductor de cobre', 'Conductor fabricado con cobre, material utilizado por sus propiedades eléctricas y mecánicas. Su aplicación requiere seleccionar un cable adecuado para la instalación.', 'informativa'),
  ((SELECT id FROM categorias WHERE nombre = 'Cables eléctricos'), 'Sección del conductor', 'Área de la sección transversal del conductor. La selección no depende de un único dato: intervienen, entre otras condiciones, la instalación, la carga prevista y la protección.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Cables eléctricos'), 'Aislación', 'Material que rodea un conductor y limita el contacto eléctrico entre este y su entorno. Debe corresponder al uso y a las condiciones de instalación.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Cables eléctricos'), 'Conductor de protección', 'Conductor que forma parte de las medidas de protección contra choques eléctricos y conecta las masas según el diseño de la instalación.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Herramientas eléctricas'), 'Multímetro', 'Instrumento de medición que, según su modelo y configuración, puede medir tensión, corriente y resistencia. Su uso requiere formación y un equipo apropiado para la medición.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Herramientas eléctricas'), 'Pinza amperométrica', 'Instrumento que permite medir corriente mediante una pinza, en las condiciones y rangos especificados por el fabricante.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Herramientas eléctricas'), 'Destornillador aislado', 'Herramienta con aislamiento diseñado para tareas eléctricas específicas. No convierte en segura una intervención sobre partes energizadas.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Herramientas eléctricas'), 'Pelacables', 'Herramienta diseñada para retirar la cubierta o aislación de conductores compatibles, sin sustituir la selección correcta de la herramienta.', 'informativa'),
  ((SELECT id FROM categorias WHERE nombre = 'Herramientas eléctricas'), 'Pinza universal', 'Herramienta manual de agarre y corte para usos generales. Su presencia no implica que sea adecuada para trabajar con tensión.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Herramientas eléctricas'), 'Buscapolo', 'Denominación de dispositivos indicadores de tensión. Sus prestaciones varían y no todos sirven para verificar ausencia de tensión.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Materiales eléctricos'), 'Caja de conexión', 'Envolvente que aloja empalmes o derivaciones de conductores y brinda protección mecánica según el modelo y su instalación.', 'informativa'),
  ((SELECT id FROM categorias WHERE nombre = 'Materiales eléctricos'), 'Caño corrugado', 'Canalización flexible corrugada destinada a alojar y proteger conductores cuando es apropiada para las condiciones de instalación.', 'informativa'),
  ((SELECT id FROM categorias WHERE nombre = 'Materiales eléctricos'), 'Canalización', 'Sistema que contiene, soporta o protege conductores. El tipo adecuado depende del entorno y de las reglas aplicables.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Materiales eléctricos'), 'Tomacorriente', 'Dispositivo de una instalación fija destinado a permitir la conexión de equipos eléctricos compatibles.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Materiales eléctricos'), 'Interruptor', 'Dispositivo que permite establecer o interrumpir un circuito dentro de las condiciones para las que fue diseñado.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Materiales eléctricos'), 'Bornera', 'Elemento con terminales destinado a conectar conductores dentro de los límites de diseño del producto.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Materiales eléctricos'), 'Tablero eléctrico', 'Conjunto que puede alojar dispositivos de maniobra, protección y distribución. Su diseño, montaje y verificación corresponden a personal competente.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Protecciones eléctricas'), 'Interruptor termomagnético', 'Dispositivo de protección contra sobrecorrientes que combina mecanismos de disparo térmico y magnético. Su selección depende del circuito y de la reglamentación aplicable.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Protecciones eléctricas'), 'Interruptor diferencial', 'Dispositivo que detecta diferencias entre corrientes y actúa según sus características. No reemplaza la protección contra sobrecorrientes ni la puesta a tierra.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Protecciones eléctricas'), 'Fusible', 'Dispositivo cuya función de protección se realiza mediante un elemento que se funde cuando la corriente supera las condiciones previstas para el producto.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Protecciones eléctricas'), 'Protector contra sobretensiones', 'Dispositivo destinado a limitar sobretensiones transitorias dentro de las condiciones de diseño especificadas por el fabricante.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Protecciones eléctricas'), 'Sistema de puesta a tierra', 'Conjunto de conductores, conexiones y elementos asociados que cumple una función dentro de las medidas de protección de una instalación.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Fallas eléctricas'), 'Cortocircuito', 'Conexión accidental de baja impedancia entre puntos con diferente potencial, que puede producir una corriente elevada y requiere protección adecuada.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Fallas eléctricas'), 'Sobrecarga', 'Condición en la que un circuito conduce una corriente superior a la prevista durante un tiempo determinado.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Fallas eléctricas'), 'Fuga de corriente', 'Corriente que circula por un camino no previsto. Su origen y riesgo deben ser evaluados por personal competente.', 'advertencia'),
  ((SELECT id FROM categorias WHERE nombre = 'Fallas eléctricas'), 'Sobretensión', 'Tensión superior a la esperada para un circuito durante un intervalo determinado. Sus causas y efectos dependen del sistema.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Fallas eléctricas'), 'Subtensión', 'Tensión inferior a la esperada para un circuito durante un intervalo determinado. Puede afectar el funcionamiento de los equipos.', 'precaucion'),
  ((SELECT id FROM categorias WHERE nombre = 'Fallas eléctricas'), 'Conexión defectuosa', 'Unión eléctrica que no cumple las condiciones requeridas de contacto o sujeción y puede provocar calentamiento o funcionamiento irregular.', 'advertencia')
